"""Bounded cache metadata and reader probes using generated byte arrays."""

import argparse
from collections import Counter
import json
import os
from pathlib import Path
import subprocess
import sys
from tempfile import TemporaryDirectory
from unittest.mock import patch

SIZE = 4096
CAPACITY = 64 * SIZE
FAKE_DXIL = b"DXBC" + bytes(SIZE - 4)
OLD_TIME = 1_600_000_000


def key(number):
    return f"{number:064x}"


def at(folder, number):
    target = key(number)
    return folder / target[:2] / f"{target}.dxil"


def set_age(path, number):
    os.utime(path, (OLD_TIME + number, OLD_TIME + number))


def bytes_on_disk(folder):
    return sum(p.stat().st_size for p in folder.glob("*/*.dxil"))


def child(action, folder, number):
    subprocess.run([sys.executable, __file__, "--source", str(args.source),
                    "--child", action, str(folder), str(number)],
                   check=True, timeout=8)


def count_pressure(folder):
    cache = ShaderCache(folder, limit_bytes=CAPACITY)
    for number in range(64):
        cache.put(key(number), FAKE_DXIL)
        set_age(at(folder, number), number)
    count = Counter()
    old_stat, old_glob = Path.stat, Path.glob

    def stat(candidate, *args, **kwargs):
        if candidate.suffix == ".dxil":
            count["file_metadata_queries"] += 1
        return old_stat(candidate, *args, **kwargs)

    def glob(path, pattern, *args, **kwargs):
        if path == folder and pattern == "*/*.dxil":
            count["directory_scans"] += 1
        return old_glob(path, pattern, *args, **kwargs)

    for number in range(64, 128):
        with patch.object(Path, "stat", stat), patch.object(Path, "glob", glob):
            cache.put(key(number), FAKE_DXIL)
        assert bytes_on_disk(folder) == CAPACITY
        assert not at(folder, number - 64).exists()
        set_age(at(folder, number), number)
    assert {p.stem for p in folder.glob("*/*.dxil")} == {key(number) for number in range(64, 128)}
    return dict(count)


def reader_control(folder):
    cache = ShaderCache(folder, limit_bytes=2 * SIZE)
    for number in range(2):
        cache.put(key(number), FAKE_DXIL)
        set_age(at(folder, number), number)
    original = at(folder, 0).stat().st_mtime_ns
    assert cache.get(key(0)) == FAKE_DXIL
    memory_unchanged = at(folder, 0).stat().st_mtime_ns == original
    child("read", folder, 0)
    disk_refresh = at(folder, 0).stat().st_mtime_ns > original
    cache.put(key(2), FAKE_DXIL)
    assert bytes_on_disk(folder) == 2 * SIZE
    return {"memory_hit_preserved_mtime": memory_unchanged,
            "external_disk_hit_refreshed_mtime": disk_refresh,
            "survivors": [number for number in range(3) if at(folder, number).exists()]}


def external_writer_control(folder):
    writer = ShaderCache(folder, limit_bytes=2 * SIZE)
    writer.put(key(0), FAKE_DXIL)
    child("write", folder, 1)
    writer.put(key(2), FAKE_DXIL)
    return {"configured_bytes": 2 * SIZE, "actual_bytes": bytes_on_disk(folder),
            "local_total": writer._total}


def error_controls(folder):
    cache = ShaderCache(folder, limit_bytes=SIZE)
    try:
        cache.put(key(0), b"invalid")
    except ValueError:
        pass
    else:
        raise AssertionError("invalid content accepted")
    cache.put(key(0), FAKE_DXIL)
    path = at(folder, 0)
    path.write_bytes(b"invalid")
    fresh = ShaderCache(folder, limit_bytes=SIZE)
    assert fresh.get(key(0)) is None and not path.exists()
    cache.put(key(1), FAKE_DXIL + bytes(1))
    assert bytes_on_disk(folder) == 0
    assert cache.get(key(1)) == FAKE_DXIL + bytes(1)
    return {"rejects_invalid": True, "cleans_corrupt_disk_entry": True,
            "overlarge_entry_not_on_disk": True, "overlarge_memory_hit": True}


parser = argparse.ArgumentParser()
parser.add_argument("--source", type=Path, default=Path(__file__).resolve().parents[1])
parser.add_argument("--child", choices=("read", "write"))
parser.add_argument("folder", nargs="?")
parser.add_argument("number", type=int, nargs="?")
args = parser.parse_args()
sys.path.insert(0, str(args.source.resolve() / "PrototypeScarlett"))
from emu.shader_cache import ShaderCache

if args.child:
    cache = ShaderCache(Path(args.folder), limit_bytes=2 * SIZE)
    if args.child == "read":
        assert cache.get(key(args.number)) == FAKE_DXIL
    else:
        cache.put(key(args.number), FAKE_DXIL)
else:
    with TemporaryDirectory(prefix="portbridge-dxil-cache-") as raw:
        folder = Path(raw)
        result = {"pressure": count_pressure(folder / "pressure"),
                  "reader": reader_control(folder / "reader"),
                  "external_writer": external_writer_control(folder / "writer"),
                  "errors": error_controls(folder / "errors")}
    print(json.dumps(result, indent=2))

